import{_ as a,o as p,c as t,a3 as e}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/32-个案讨论.md","filePath":"books/attached/32-个案讨论.md","lastUpdated":1794316978000}'),o={name:"books/attached/32-个案讨论.md"};function r(n,_,s,d,c,i){return p(),t("div",null,[..._[0]||(_[0]=[e('<h3 id="个案讨论" tabindex="-1">个案讨论 <a class="header-anchor" href="#个案讨论" aria-label="Permalink to &quot;个案讨论&quot;">​</a></h3><p>读完下面的个案描述，你能不能判断出每个主人公的依恋风格呢？如果想要检验自己的评估能力，就先用纸把答案盖上，用心把上面表格中提到的每种风格的行为特征，以及判断这些风格的“黄金法则”牢牢记住吧。</p><p>1.巴里（Barry），离异，46岁</p><p>别跟我提亲密关系！我现在还沉浸在离婚的痛苦中难以自拔。我很想回到没有离婚之前，很想为女人所爱，也很想有稳定的性生活。不过我知道自己应该谨慎一些，一旦我开始一段新的恋情，马上就要面临一连串的麻烦，比如说怎么给她的孩子当一位好爸爸，以及谈婚论嫁的种种琐事。其实我已经和一位名叫凯特琳（Caitlin）的女士交往快一年了，她各方面的条件也都很不错。我知道她在很认真地对待我们的关系，但是对我来说，实在需要很长的时间去重新信赖、承诺并深爱另一个女人。而且即便我们真的确定关系，我也有一些自己的底线不能触碰。比如说，我的伴侣必须要做到经济独立，因为我当初快被我前妻榨干了钱财，实在是不能负担两个女人的生活！当然，除此之外，我还有一些原则，同样也不能妥协。</p><p>巴里的依恋风格是：___________________________解答：巴里属于回避型。你恐怕会告诉自己，这个家伙只不过是受了婚姻的创伤，从此变得小心翼翼而已。即使如此，我们还是可以从他自述的字里行间，判断出他是个回避型依恋风格的人。他说自己即使已经坠入爱河，仍然要遵循着不能妥协的铁律，他对自己的独立性视若珍宝，他还十分多疑。特别值得注意的是，他甚至谈到了对方的孩子，这里所说的是交往对象在上一段婚姻里，跟前任所生的孩子，这种表述就带着一种强烈的疏远感。他很怕女人利用自己，用经济手段在婚姻中给他套上枷锁。只要参见“黄金法则”第一条：确认对方是否渴望亲密的行为。你就会发现，他丝毫没有对亲密的渴望。他的确说到自己渴望性爱，但是并没有提及任何情感上的支持与亲近感。</p><p>2.贝拉（Bella），单身，24岁</p><p>我跟马克（Mark）交往一年半了。跟他在一起非常开心，不过别误会，毕竟每段关系都不会十全十美，所以我们也会有些小分歧。刚开始交往的时候，马克就有些地方让我有点不满。比如说，我们刚认识的时候，马克在性爱方面没什么经验，说实话，在床上，我得对他进行一点指导。毕竟我不希望下半辈子性生活都不和谐！不过还好，这都是过去的事了。另外，与他相比，我是个非常外向的人，而他则比较严谨，做事十分踏实。实话说吧，刚开始我觉得他完全配不上我。不过后来我相信自己的决定是再好不过了，他真的很温暖，很可靠，这些品格都是无比珍贵的，我真是越来越爱他了！</p><p>贝拉的依恋风格是：_______________________解答：贝拉属于安全型依恋风格。对于贝拉属于安全型依恋风格，最为清晰而重要的线索，就是她会在床上指导马克。这是与伴侣进行清晰而有效沟通的一个很好的典范。她的确会遇到问题，同时她会积极解决，也对自己的解决能力很有信心。如果贝拉是焦虑型，她就会将马克在床上的表现不良，归咎于自己的头上。她可能会觉得自己不够有魅力，不足以吸引对方，因此才不能满足她。而相应的，贝拉对此只会默默忍受，尽量不去破坏彼此的关系。如果贝拉是回避型，她便不会归因于自己，而会就马克的不足而藐视他，她会采取疏远的策略，而非将自己的使用技巧教授给对方。另外，贝拉对于恋爱关系的随和态度，也能体现她属于安全型依恋风格。虽然马克一开始并不属于她的“理想伴侣”范畴，但是她自己就转变了心态，并没有产生太大的内在冲突。更重要的是，她是打心眼儿里对自己的决定非常满意。而如果她属于回避型，可能也会做出类似的妥协，然而不同的是，她可能会对自己的决定感到非常不甘心。最后一点在于，贝拉会将自己的感受，开诚布公地传达给马克，这也能够证明她属于安全型。</p><p>3.珍妮特（Janet），单身，23岁</p><p>我跟蒂姆（Tim）才一块儿出来两次，就感觉深深爱上了他，我似乎找到了心目中那个理想型，他真的是个很棒的人。我对恋人的要求比较苛刻，只愿意和特定类型的男人交往，因此要找到一个合适的对象其实挺难的。而对方也同样喜欢我的概率，就更是微乎其微了。因此我遇到蒂姆以后，必须得确保自己做的一切都万无一失。然而犯错误总是难免的，每当做错事情，我就会担心整段感情的安危。我很希望一切都由他来决定，这样我就不用看起来太过主动了。是不是只要给他发一条短信就够了？你不觉得那样看上去比较漫不经心吗？或许我可以把他加入我的群发通讯录列表，然后不时地发送一些搞笑小邮件……</p><p>珍妮特的依恋风格是：_______________________解答：珍妮特属于典型的焦虑型依恋风格。她觉得自己似乎不够完整，因此寻求亲密感，也对感情非常投入。诚然，无论何种依恋风格的人在刚开始恋爱的时候，都会对对方产生极大的兴趣，甚至日思夜想。但是珍妮特显然远远超过了这个地步，她将感情看得极其来之不易，觉得自己任何一点细微的失当行为，都足以摧毁这段感情。因此，她无时无刻不在绞尽脑汁，想尽办法不出任何“差错”。与此同时，她将感情的主动权交给蒂姆。她还因为自己的不安全感，而在感情中玩一些小把戏，处心积虑地想要隐晦地与蒂姆搭上关系，又不会显得自己太不矜持。比如将蒂姆放在群发列表里，借机发邮件给他，就是个很典型的此类把戏。</p><p>4.保罗（Paul），单身，37岁</p><p>我刚刚跟阿曼达（Amanda）分手，虽然非常痛心，但是也清楚地知道，自己与她并没有相守一生的可能。我们交往了几个月，一开始我真的觉得找到了自己梦中的女神。但是渐渐地，她就开始令我困扰了。比如，我发现她竟然整过容，这实在是太倒我的胃口了。与此同时，她对自己极度不自信，这点也让我很不喜欢。每当我对一个人失去兴趣，再跟她共处一分钟对我来说都是煎熬。我坚信对的人会在某处等着我与之相遇，不管需要多久，我们都会找到彼此，共度一生。这是一种发自肺腑的感觉，我甚至能看到她的笑靥，感受到她的拥抱。我知道一旦我们相遇，就能马上感觉到一种淡泊和宁静。因此不管有多艰难，我保证一定不会停止寻找。</p><p>保罗的依恋风格是：_______________________解答：保罗属于回避型依恋风格。不过这个案例判断起来比较困难。保罗有着自己的理想型，因此有人肯定会觉得，他要么是安全型，要么是焦虑型，对吗？然而并非如此。他对于理想中“真爱”的描述，值得引起我们的关注。另外，不同依恋类型的人，对于自己为何一直单身的解释也是迥然不同的：焦虑型的人会觉得，这一切都是自己不够好的缘故；安全型的人会找一些比较客观的原因；而回避型的人，往往就会像保罗一样，他们会将自己的单身归咎于外部因素，比如说遇不到对的人。这倒是一个非常好的机会，能够从他们所说的话中发现一些隐含的端倪：如果你不能理解，为什么这些人看上去阅人无数，却总是没有遇上合适的人，这时候你就需要解读他的言外之意了。在保罗对于他和阿曼达恋情的描述中，也暗含了这层意思：一开始他是对阿曼达非常着迷的，但当关系越来越亲密以后，他就会发现对方身上有令他失望的地方。而在关系日渐亲密之后对恋人的兴趣减弱，就是回避型依恋风格人群的典型特征，事实上，这是他们想要疏远对方的一种策略。</p><p>5.罗根（Logan），单身，34岁</p><p>玛丽（Mary）是我的第三任女友，也是迄今为止的最后一任。几年前我们刚认识时，玛丽还对我如此简单的情史表示怀疑。她不断地逼问我过去的感情史，直到后来，她意识到我已经将所有的感情经历都向她和盘托出了，可她对此感到非常困惑，她问我说，难道不觉得感情有些单薄？难道单身那么久不会觉得焦虑吗？难道没有与人恋爱的欲望吗？说句实话，找不到对象这件事，我从没放在心上过。当然，有时候孤单失落也是难免的，但是我坚信，只要时间对了，一切都会水到渠成的。当我发现自己爱上玛丽的那一刻，我就立马向她表白了。我倒是不确定她是不是也和我同时坠入爱河，不过能看出来，在她对我表白心迹之前，就已经爱上我了。</p><p>罗根的依恋风格是：_______________________解答：罗根属于安全型依恋风格。有以下几点可以证明。首先，他并没有对感情过度投入，也不担心自己落单，而这两点恰好是焦虑型依恋风格的典型特征，他女朋友玛丽就有这种倾向。因此罗根要么是安全型，要么是回避型。还有一些线索表明，他也不是回避型。其一，他并不向玛丽隐瞒自己过去的情史，什么都放到台面上明说，也并不因为玛丽的纠缠而生气，也并没有像焦虑型人群一样，贬低自己的前任来取悦现任。其二，他一开始就将自己的爱慕之情表白给了玛丽，这也是典型的安全型特质。如果他是回避型，这时候会显得若即若离。再者，他也没有在感情中玩什么小把戏，他并没有纠结于玛丽是否接受他。他的一切言行都是直觉使然，并没有经过什么斟酌谋虑。</p><p>6.苏珊娜（Suzanne），单身，33岁</p><p>每到情人节，就预示着我的脱单战役又打了一年，我真的很想找个人结婚。我讨厌孤单，讨厌每天回到空无一人的房子，讨厌独自去看电影，讨厌自慰或者约炮。今年我一定要找到一个属于我的好男人！过去，我总是对恋人倾其所有，但最后都是失败告终。我甚至不再相信自己能找个好人，但是，我必须克服对创伤的恐惧！为了结束单身，我真是豁出去了，我愿意冒一切风险甚至失去自我。我深知一分耕耘一分收获的道理，如果我不敞开心扉，那个对的人就没有机会走进我的人生。我绝不会向绝望屈服，一定会找到自己的幸福！</p><p>苏珊娜的依恋风格是：_______________________解答：苏珊娜属于焦虑型依恋风格。这是一个典型的受过多次情伤的焦虑型女性。她非常执着于找一个伴儿。她很想走出往日的阴霾，寻找到自己的灵魂伴侣，但是由于自己对于依恋理论知识的缺乏，她并不能判断出谁值得信任，谁又需要远离。苏珊娜与案例4中的保罗相比，形成了很大的反差。她并不执着于找到“理想的”伴侣。我们很容易找到她单身的根本原因：每当寻求亲密遭受伤害以后，她仍然有着对亲密感的极度渴望。而保罗则不同，在他找到心目中的“完美女人”之前，对眼前的亲密关系毫无兴趣。</p>',20)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
